tape( 'the function returns a reference to the output array', function test( t ) {
	var out;
	var x;
	var y;
	var z;

	x = [ 3.0, 5.0 ];
	y = [ 1.0, 4.0 ];
	out = [ 0.0, 0.0, 0.0, 0.0 ];
	z = gcauchyMatrix( x.length, y.length, x, 1, 0, y, 1, 0, out, 2, 1, 0 );

	t.strictEqual( z, out, 'same reference' );
	t.end();
});

tape( 'if provided an `M` or `N` parameter equal to `0`, the function returns the output array unchanged', function test( t ) {
	var expected;
	var out;
	var x;
	var y;

	x = [ 3.0, 5.0 ];
	y = [ 1.0, 4.0 ];
	out = [ 5.0, 6.0, 7.0, 8.0 ];
	expected = [ 5.0, 6.0, 7.0, 8.0 ];

	gcauchyMatrix( 0, y.length, x, 1, 0, y, 1, 0, out, 2, 1, 0 );
	t.deepEqual( out, expected, 'returns expected value' );

	gcauchyMatrix( x.length, 0, x, 1, 0, y, 1, 0, out, 2, 1, 0 );
	t.deepEqual( out, expected, 'returns expected value' );

	t.end();
});

